/*
 * The consumer used by the `package` job in .github/workflows/ci.yml and by the
 * `package` step of ci/check.sh.
 *
 * It lives in the repository, rather than being generated by the workflow, for
 * one specific reason: an earlier version *was* generated by the workflow, and
 * when ql_allocator_t moved from ql_common.h to ql_mem.h the workflow's copy
 * silently stopped compiling while the hand-written copy used for local
 * verification kept working. Two copies of the same fixture is one copy too
 * many.
 *
 * It includes the umbrella header on purpose, since that is the documented way
 * in and the thing a consumer is most likely to get wrong.
 */

#include <qlib/qlib.h>

#include <stdio.h>

int main(void)
{
    ql_allocator_t alloc = ql_default_allocator();
    void* block;

    block = ql_alloc(&alloc, 64);
    if (block == NULL)
    {
        return 1;
    }
    ql_dealloc(&alloc, block);

    printf("qlib %s\n", ql_version());
    return 0;
}
